def find_password(input_string):
    n = len(input_string)
    for x in range(n):
        for l in range(1, n - 2 * x + 1):
            if l % 2 == 1:
                prefix = input_string[:x]
                middle = input_string[x:x + l]
                suffix = input_string[x + l:]
                if prefix + middle + suffix == (prefix + middle + suffix)[::-1]:
                    yield (x + 1, l)

input_string = input().strip()
